#[derive(Debug)]
struct Robot {
    position: i32,
    health: i32,
    direction: char,
    index: usize,
}

impl Solution {
    pub fn survived_robots_healths(positions: Vec<i32>, healths: Vec<i32>, directions: String) -> Vec<i32> {
        let n = positions.len();
        let mut vals: Vec<Robot> = (0..n)
            .map(|i| Robot {
                position: positions[i],
                health: healths[i],
                direction: directions.chars().nth(i).unwrap(),
                index: i,
            })
            .collect();
        vals.sort_by_key(|x| x.position);
        let mut stack: Vec<Robot> = Vec::new();
        for robot in vals {
            if robot.direction == 'R' {
                stack.push(robot);
                continue;
            }
            let mut gone = false;
            while let Some(last) = stack.last_mut() {
                if last.direction != 'R' || last.health > robot.health {
                    break;
                }
                if last.health == robot.health {
                    stack.pop();
                    gone = true;
                    break;
                }
                robot.health -= 1;
                stack.pop();
            }
            if !gone {
                if let Some(last) = stack.last_mut() {
                    if last.direction == 'R' && last.health > robot.health {
                        last.health -= 1;
                        gone = true;
                    }
                }
            }
            if !gone {
                stack.push(robot);
            }
        }
        stack.sort_by_key(|x| x.index);
        stack.into_iter().map(|x| x.health).collect()
    }
}
